function withTimeout(promise, ms){
  return Promise.race([
    promise,
    new Promise((_, reject) => setTimeout(()=>reject(new Error('timeout')), ms))
  ]);
}

/* MySQL es el almacenamiento principal. El almacenamiento del navegador solo
   se usa como respaldo y nunca cuenta como confirmación de guardado remoto. */
const API_URL = '../Backend/api.php';
let storageBackendError = null;
let storageNeedsSync = false;

async function phpGet(key){
  const res = await withTimeout(fetch(`${API_URL}?clave=${encodeURIComponent(key)}`), 4000);
  if(!res.ok) throw new Error('La API de almacenamiento respondió con error.');
  const data = await res.json();
  return data.valor ?? null;
}
async function phpSet(key, value){
  const res = await withTimeout(fetch(API_URL, {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({clave: key, valor: value})
  }), 4000);
  if(!res.ok) throw new Error('La API de almacenamiento respondió con error.');
  const data = await res.json();
  if(data.ok !== true) throw new Error(data.error || 'La API no confirmó el guardado.');
}

async function storageGet(key){
  let remoteValue;
  try{
    remoteValue = await phpGet(key);
    storageBackendError = null;
    if(remoteValue !== null){
      try{ localStorage.setItem(key, remoteValue); }catch(e){}
      return remoteValue;
    }
    storageNeedsSync = true;
  }catch(e){
    storageBackendError = e;
    storageNeedsSync = true;
    console.error('No se pudieron leer los datos de MySQL.', e);
  }
  try{
    if(window.storage && typeof window.storage.get === 'function'){
      const res = await withTimeout(window.storage.get(key, false), 3000);
      if(res && res.value){
        storageNeedsSync = true;
        return res.value;
      }
    }
  }catch(e){}
  try{
    const v = localStorage.getItem(key);
    if(v){
      storageNeedsSync = true;
      return v;
    }
  }catch(e){}
  return null;
}
async function storageSet(key, value){
  try{
    await phpSet(key, value);
    storageBackendError = null;
    storageNeedsSync = false;
  }catch(e){
    storageBackendError = e;
    try{ localStorage.setItem(key, value); }catch(cacheError){
      console.error('No se pudo actualizar el respaldo local.', cacheError);
    }
    console.error('No se pudieron guardar los datos en MySQL.', e);
    throw new Error('No se guardó en la base de datos de EasyPanel. Verifica AUTOCTRL_DB_* y que exista la tabla almacenamiento.');
  }
  try{
    if(window.storage && typeof window.storage.set === 'function'){
      await withTimeout(window.storage.set(key, value, false), 3000);
    }
  }catch(e){}
  try{ localStorage.setItem(key, value); }catch(e){}
  return true;
}

/* Genera precios por cantidad (1/4, 2/4, 3/4, 1 galón) a partir del precio
   de referencia de un servicio de cambio de aceite, redondeando a miles. */
function generarOpcionesCantidad(precioBase){
  const p = Number(precioBase)||0;
  const round = n => Math.round(n/1000)*1000;
  return [
    {cantidad:'1/4', precio: round(p*0.30)},
    {cantidad:'2/4', precio: round(p*0.55)},
    {cantidad:'3/4', precio: round(p*0.80)},
    {cantidad:'1',   precio: p}
  ];
}
/* Corrige datos guardados de versiones anteriores: cualquier servicio de
   'Cambio de aceite' que no tenga precios por cantidad los recibe ahora,
   para que aparezcan en todos los vehículos sin perder el resto de datos. */
function normalizarServicios(){
  let cambios = false;
  (state.data.servicios||[]).forEach(s=>{
    if(s.categoria === 'Cambio de aceite' && !s.opcionesCantidad){
      s.opcionesCantidad = generarOpcionesCantidad(s.precio);
      if(!s.tipoAceite) s.tipoAceite = 'No especificado';
      cambios = true;
    }
  });
  return cambios;
}

/* Migra facturas y alertas guardadas con el campo antiguo 'servicioId' (un solo
   servicio) al nuevo campo 'servicioIds' (arreglo, permite varios servicios).
   Así los datos que ya tenían los talleres guardados siguen funcionando. */
function normalizarMultiServicio(){
  let cambios = false;
  ['facturas','alertas'].forEach(key=>{
    (state.data[key]||[]).forEach(item=>{
      if(!item.servicioIds){
        item.servicioIds = item.servicioId ? [item.servicioId] : [];
        cambios = true;
      }
      if('servicioId' in item){ delete item.servicioId; cambios = true; }
    });
  });
  if(!state.data.solicitudes){ state.data.solicitudes = []; cambios = true; }
  return cambios;
}
function normalizarImagenServicios(){
  let cambios=false;
  (state.data.servicios||[]).forEach(s=>{ if(s.imagen===undefined){ s.imagen=null; cambios=true; } });
  return cambios;
}
function reglasRecordatorioPredeterminadas(){
  return [
    {id:'mes-antes', cantidad:1, unidad:'mes', momento:'antes', activo:true},
    {id:'15-dias', cantidad:15, unidad:'dia', momento:'antes', activo:true},
    {id:'8-dias', cantidad:8, unidad:'dia', momento:'antes', activo:true},
    {id:'5-dias', cantidad:5, unidad:'dia', momento:'antes', activo:true},
    {id:'3-dias', cantidad:3, unidad:'dia', momento:'antes', activo:true},
    {id:'1-dia', cantidad:1, unidad:'dia', momento:'antes', activo:true},
    {id:'mismo-dia', cantidad:0, unidad:'dia', momento:'mismo-dia', activo:true},
    {id:'vencido-1-dia', cantidad:1, unidad:'dia', momento:'despues', activo:true}
  ];
}

async function loadData(){
  let shouldSaveInitialData = false;
  try{
    const raw = await storageGet(STORAGE_KEY);
    state.data = raw ? JSON.parse(raw) : seedData();
    if(!state.data.auth) state.data.auth = {usuario:'admin', password:'1234'};
    // migrar vehiculo en clientes existentes
    (state.data.clientes||[]).forEach(c=>{ if(!c.vehiculo){ c.vehiculo='Automóvil'; } });
    if(!state.data.config) state.data.config = {nombreTaller:'Taller Lubricantes Molina', direccion:'Yopal, Casanare', telefono:'', whatsapp:'', logo:null};
    const huboCambios1 = normalizarServicios();
    const huboCambios2 = normalizarMultiServicio();
    const huboCambios3 = normalizarImagenServicios();
    const huboCambios4 = !Array.isArray(state.data.config.reglasRecordatorio);
    if(huboCambios4) state.data.config.reglasRecordatorio = reglasRecordatorioPredeterminadas();
    const huboCambios5 = !state.data.config.recordatoriosAutomaticos;
    if(huboCambios5) state.data.config.recordatoriosAutomaticos = {activo:false, ultimaRevision:null};
    const huboCambios6 = normalizarMantenimientos();
    shouldSaveInitialData = !raw || storageNeedsSync || huboCambios1 || huboCambios2 || huboCambios3 || huboCambios4 || huboCambios5 || huboCambios6;
  }catch(e){
    state.data = seedData();
  }
  state.view = 'welcome';
  render();
  if(shouldSaveInitialData){
    try{
      await persist();
    }catch(e){
      showToast(e.message, true);
      return;
    }
  }
  if(storageBackendError){
    showToast('No hay conexión con la base de datos. Los datos de esta sesión podrían no guardarse en EasyPanel.', true);
  }
}
async function persist(){
  await storageSet(STORAGE_KEY, JSON.stringify(state.data));
}

/* ================= HELPERS ================= */
const $ = sel => document.querySelector(sel);
function fmtMoney(n){ return '$' + Number(n||0).toLocaleString('es-CO'); }
function uid(){ return 't'+Date.now()+Math.floor(Math.random()*1000); }
function fechaHoyBogota(){
  const partes = new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  const valores = Object.fromEntries(partes.map(p=>[p.type,p.value]));
  return `${valores.year}-${valores.month}-${valores.day}`;
}
