function intervaloRecomendadoServicio(servicio){
  const nombre = (servicio?.nombre||'').toLowerCase();
  const categoria = (servicio?.categoria||'').toLowerCase();
  const moto = (servicio?.vehiculos||[]).includes('Motocicleta');
  if(nombre.includes('aceite')) return {km:moto?3000:5000,dias:180};
  if(nombre.includes('filtro de aceite')) return {km:moto?3000:5000,dias:180};
  if(nombre.includes('filtro de aire')) return {km:moto?8000:12000,dias:365};
  if(nombre.includes('filtro de combustible')) return {km:20000,dias:365};
  if(nombre.includes('banda')) return {km:40000,dias:730};
  if(nombre.includes('rotación')||nombre.includes('rotacion')||nombre.includes('balanceo')||nombre.includes('alineación')||nombre.includes('alineacion')) return {km:10000,dias:180};
  if(nombre.includes('llanta')) return {km:nombre.includes('rotación')||nombre.includes('rotacion')?10000:40000,dias:730};
  if(nombre.includes('pastillas')||nombre.includes('freno')) return {km:20000,dias:365};
  if(nombre.includes('refrigerante')) return {km:40000,dias:730};
  if(nombre.includes('bujía')||nombre.includes('bujia')) return {km:20000,dias:365};
  if(nombre.includes('batería')||nombre.includes('bateria')) return {km:15000,dias:365};
  if(nombre.includes('lubricación')||nombre.includes('lubricacion')||nombre.includes('engrase')) return {km:5000,dias:180};
  if(categoria==='suspensión'||categoria==='suspension') return {km:15000,dias:365};
  return {km:10000,dias:180};
}
function sumarDiasFecha(fecha,dias){
  const [year,month,day]=fecha.split('-').map(Number);
  const result=new Date(Date.UTC(year,month-1,day+Math.max(0,Math.round(dias))));
  return `${result.getUTCFullYear()}-${String(result.getUTCMonth()+1).padStart(2,'0')}-${String(result.getUTCDate()).padStart(2,'0')}`;
}
function usoDiarioKmEstimado(factura){
  const lecturas=(state.data.facturas||[]).filter(f=>f.clienteId===factura.clienteId&&f.placa===factura.placa&&f.id!==factura.id&&f.kmActual!=null&&f.kmActual!==''&&Number.isFinite(Number(f.kmActual))&&f.fecha)
    .map(f=>({fecha:f.fecha,km:Number(f.kmActual)}));
  if(factura.kmActual!=null&&factura.kmActual!==''&&Number.isFinite(Number(factura.kmActual))) lecturas.push({fecha:factura.fecha,km:Number(factura.kmActual)});
  lecturas.sort((a,b)=>a.fecha.localeCompare(b.fecha));
  const tasas=[];
  for(let i=1;i<lecturas.length;i++){
    const dias=(new Date(lecturas[i].fecha+'T00:00:00')-new Date(lecturas[i-1].fecha+'T00:00:00'))/86400000;
    const km=lecturas[i].km-lecturas[i-1].km;
    if(dias>0&&km>0&&km/dias<1000) tasas.push(km/dias);
  }
  const recientes=tasas.slice(-3);
  return recientes.length?recientes.reduce((sum,tasa)=>sum+tasa,0)/recientes.length:0;
}
function estimarProximoMantenimiento(factura,servicio){
  const recomendado=intervaloRecomendadoServicio(servicio);
  const intervaloKm=Number(servicio.intervaloKm)||recomendado.km;
  const intervaloDias=Number(servicio.intervaloDias)||recomendado.dias;
  const kmActual=factura.kmActual!=null&&factura.kmActual!==''&&Number.isFinite(Number(factura.kmActual))?Number(factura.kmActual):null;
  const kmProximo=kmActual==null?null:kmActual+intervaloKm;
  const fechaPorTiempo=sumarDiasFecha(factura.fecha,intervaloDias);
  const usoDiario=usoDiarioKmEstimado(factura);
  const diasPorKilometraje=usoDiario>0?Math.ceil(intervaloKm/usoDiario):null;
  const fechaPorKilometraje=diasPorKilometraje==null?null:sumarDiasFecha(factura.fecha,diasPorKilometraje);
  const fechas=[fechaPorTiempo,fechaPorKilometraje].filter(Boolean).sort();
  return {intervaloKm,intervaloDias,kmActual,kmProximo,usoDiario,fechaProxima:fechas[0]||fechaPorTiempo};
}
function sincronizarMantenimientosFactura(factura){
  if(!Array.isArray(state.data.mantenimientos)) state.data.mantenimientos=[];
  if(!Array.isArray(state.data.alertas)) state.data.alertas=[];
  const ids=new Set(factura.servicioIds||[]);
  const removed=state.data.mantenimientos.filter(m=>m.facturaId===factura.id&&!ids.has(m.servicioId));
  removed.forEach(m=>{ state.data.alertas=state.data.alertas.filter(a=>a.id!==m.alertaId); });
  state.data.mantenimientos=state.data.mantenimientos.filter(m=>m.facturaId!==factura.id||ids.has(m.servicioId));
  (factura.servicioIds||[]).forEach(servicioId=>{
    const servicio=state.data.servicios.find(s=>s.id===servicioId);
    if(!servicio) return;
    const calculado=estimarProximoMantenimiento(factura,servicio);
    let registro=state.data.mantenimientos.find(m=>m.facturaId===factura.id&&m.servicioId===servicioId);
    if(!registro){ registro={id:uid(),facturaId:factura.id,servicioId,estado:'activo'}; state.data.mantenimientos.push(registro); }
    Object.assign(registro,{
      clienteId:factura.clienteId,placa:factura.placa,fechaServicio:factura.fecha,
      kmActual:calculado.kmActual,kmProximo:calculado.kmProximo,
      intervaloKm:calculado.intervaloKm,intervaloDias:calculado.intervaloDias,
      usoDiarioKm:calculado.usoDiario,fechaProxima:calculado.fechaProxima
    });
    let alerta=state.data.alertas.find(a=>a.id===registro.alertaId);
    if(!alerta){
      alerta=state.data.alertas.find(a=>a.clienteId===factura.clienteId&&a.fecha===calculado.fechaProxima&&(a.servicioIds||[]).includes(servicioId)&&!a.mantenimientoId);
      if(alerta) registro.alertaId=alerta.id;
    }
    if(!alerta){
      alerta={id:uid(),clienteId:factura.clienteId,placa:factura.placa,servicioIds:[servicioId],fecha:calculado.fechaProxima,descripcion:'Recordatorio de mantenimiento estimado',estado:registro.estado==='finalizado'?'realizada':'pendiente',notificarWhatsapp:true,notificarCorreo:false,mantenimientoId:registro.id,recordatoriosEnviados:{}};
      state.data.alertas.push(alerta);
      registro.alertaId=alerta.id;
    }else{
      alerta.clienteId=factura.clienteId; alerta.placa=factura.placa; alerta.servicioIds=[servicioId];
      alerta.fecha=calculado.fechaProxima; alerta.mantenimientoId=registro.id;
      alerta.estado=registro.estado==='finalizado'?'realizada':'pendiente';
    }
  });
}
function recalcularMantenimientosServicio(servicioId){
  const servicio=state.data.servicios.find(s=>s.id===servicioId);
  if(!servicio) return;
  (state.data.mantenimientos||[]).filter(m=>m.servicioId===servicioId&&m.estado==='activo').forEach(m=>{
    const factura=state.data.facturas.find(f=>f.id===m.facturaId);
    if(!factura) return;
    const calculado=estimarProximoMantenimiento(factura,servicio);
    Object.assign(m,{kmActual:calculado.kmActual,kmProximo:calculado.kmProximo,intervaloKm:calculado.intervaloKm,intervaloDias:calculado.intervaloDias,usoDiarioKm:calculado.usoDiario,fechaProxima:calculado.fechaProxima});
    const alerta=state.data.alertas.find(a=>a.id===m.alertaId);
    if(alerta) alerta.fecha=calculado.fechaProxima;
  });
}
function normalizarMantenimientos(){
  let cambios=false;
  if(!Array.isArray(state.data.mantenimientos)){ state.data.mantenimientos=[]; cambios=true; }
  (state.data.facturas||[]).forEach(f=>{
    const faltantes=(f.servicioIds||[]).some(id=>!state.data.mantenimientos.some(m=>m.facturaId===f.id&&m.servicioId===id));
    if(faltantes){ sincronizarMantenimientosFactura(f); cambios=true; }
  });
  return cambios;
}
