/* ======= HORARIOS Y DISPONIBILIDAD ======= */
function getHorarioConfig(){
  const c = state.data.config || {};
  return {
    abre: c.horarioAbre || '08:00',
    cierra: c.horarioCierra || '18:00',
    sabado: c.horarioSabado !== false,
    sabadoCierra: c.horarioSabadoCierra || '12:00'
  };
}
function generarHoras(pasoMinutos, horaInicio, horaFin){
  const horas = [];
  const [hi, mi] = horaInicio.split(':').map(Number);
  const [hf, mf] = horaFin.split(':').map(Number);
  let totalMin = hi*60 + mi;
  const totalFin = hf*60 + mf;
  while(totalMin <= totalFin){
    const h = Math.floor(totalMin/60);
    const m = totalMin % 60;
    horas.push(`${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}`);
    totalMin += pasoMinutos;
  }
  return horas;
}
function getHorasDisponibles(fechaStr){
  if(!fechaStr) return [];
  const cfg = getHorarioConfig();
  const d = new Date(fechaStr + 'T00:00:00');
  const dia = d.getDay();
  if(dia === 0){ return []; }
  if(dia === 6 && !cfg.sabado){ return []; }
  const cierre = (dia === 6) ? cfg.sabadoCierra : cfg.cierra;
  const todas = generarHoras(30, cfg.abre, cierre);
  const ocupadas = horasOcupadas(fechaStr);
  const hoy = new Date().toISOString().slice(0,10);
  const ahora = new Date();
  const horaActual = `${String(ahora.getHours()).padStart(2,'0')}:${String(ahora.getMinutes()).padStart(2,'0')}`;
  return todas.filter(h => {
    if(ocupadas.has(h)) return false;
    if(fechaStr === hoy && h <= horaActual) return false;
    return true;
  });
}
function getHorasFacturaDisponibles(fechaStr){
  if(!fechaStr) return [];
  const dia = new Date(fechaStr + 'T00:00:00').getDay();
  const cfg = getHorarioConfig();
  if(dia === 0 || (dia === 6 && !cfg.sabado)) return [];
  const horas = [
    ...generarHoras(15, '08:00', '11:00'),
    ...generarHoras(15, '14:00', '17:00')
  ];
  const cierre = dia === 6 ? cfg.sabadoCierra : '17:00';
  const ocupadas = horasOcupadas(fechaStr);
  return horas.filter(h => h <= cierre && !ocupadas.has(h));
}
function horasOcupadas(fechaStr){
  const ocup = new Set();
  const existentes = [
    ...(state.data.facturas||[]).filter(f=>f.fecha===fechaStr).map(f=>({hora:f.hora})),
    ...(state.data.solicitudes||[]).filter(s=>s.fecha===fechaStr).map(s=>({hora:s.hora})),
    ...(state.data.alertas||[]).filter(a=>a.fecha===fechaStr).map(a=>({hora:a.hora})),
    ...(state.data.pedidos||[]).filter(p=>p.fechaRetiro===fechaStr).map(p=>({hora:p.horaRetiro}))
  ];
  existentes.forEach(e => { if(e.hora) ocup.add(e.hora); });
  return ocup;
}
function validarFechaHora(fechaStr, horaStr){
  if(!fechaStr) return {ok:false, msg:'Selecciona una fecha.'};
  if(!horaStr) return {ok:false, msg:'Selecciona una hora.'};
  const d = new Date(fechaStr + 'T' + horaStr + ':00');
  const ahora = new Date();
  if(d < ahora) return {ok:false, msg:'No puedes seleccionar una fecha u hora en el pasado.'};
  const disponibles = getHorasDisponibles(fechaStr);
  if(disponibles.length === 0){
    const dia = new Date(fechaStr + 'T00:00:00').getDay();
    if(dia === 0) return {ok:false, msg:'El taller está cerrado los domingos.'};
    if(dia === 6) return {ok:false, msg:'El taller no atiende los sábados.'};
    return {ok:false, msg:'No hay horarios disponibles para esta fecha.'};
  }
  if(!disponibles.includes(horaStr)){
    return {ok:false, msg:`La hora ${horaStr} no está disponible. Horarios disponibles: ${disponibles.join(', ')}`};
  }
  return {ok:true};
}
function validarHoraFactura(fechaStr, horaStr, facturaId){
  if(!fechaStr) return {ok:false, msg:'Selecciona una fecha.'};
  if(!horaStr) return {ok:false, msg:'Selecciona una hora.'};
  const facturaActual = facturaId ? state.data.facturas.find(f=>f.id===facturaId) : null;
  if(facturaActual && facturaActual.fecha===fechaStr && facturaActual.hora===horaStr){
    return {ok:true};
  }
  const horaSeleccionada = new Date(fechaStr + 'T' + horaStr + ':00');
  const ahora = new Date();
  ahora.setSeconds(0, 0);
  if(horaSeleccionada > ahora){
    return {ok:false, msg:'No puedes seleccionar una fecha u hora futura.'};
  }
  const disponibles = getHorasFacturaDisponibles(fechaStr);
  if(!disponibles.length){
    const dia = new Date(fechaStr + 'T00:00:00').getDay();
    if(dia === 0) return {ok:false, msg:'El taller está cerrado los domingos.'};
    if(dia === 6 && !getHorarioConfig().sabado) return {ok:false, msg:'El taller no atiende los sábados.'};
    return {ok:false, msg:'No hay horarios disponibles para esta fecha.'};
  }
  if(!disponibles.includes(horaStr)){
    return {ok:false, msg:`La hora ${horaStr} no está disponible. Selecciona un horario libre.`};
  }
  return {ok:true};
}
function selectorHorasOptions(fechaStr, seleccionada){
  const disponibles = getHorasDisponibles(fechaStr);
  if(!disponibles.length){
    return '<option value="">Sin cupos disponibles</option>';
  }
  return disponibles.map(h => `<option value="${h}" ${h===seleccionada?'selected':''}>${h}</option>`).join('');
}
function selectorHorasFacturaOptions(fechaStr, seleccionada){
  const horas = [
    ...generarHoras(15, '08:00', '11:00'),
    ...generarHoras(15, '14:00', '17:00')
  ];
  return horas.map(h => {
    const [hora, minuto] = h.split(':').map(Number);
    const sufijo = hora < 12 ? 'am' : 'pm';
    const hora12 = hora % 12 || 12;
    return `<option value="${h}" ${h===seleccionada?'selected':''}>${hora12}:${String(minuto).padStart(2,'0')}${sufijo}</option>`;
  }).join('');
}
function onFechaHoraChange(fechaId, horaId){
  const fecha = document.getElementById(fechaId);
  const hora = document.getElementById(horaId);
  if(!fecha || !hora) return;
  const sel = hora.value;
  hora.innerHTML = horaId === 'fact-hora'
    ? selectorHorasFacturaOptions(fecha.value, sel)
    : selectorHorasOptions(fecha.value, sel);
}


function showToast(msg, isError){
  const t = $('#toast');
  t.innerHTML = (isError ? '⚠️ ' : '✅ ') + esc(msg);
  t.style.background = isError ? 'var(--danger-dark)' : 'var(--navy)';
  t.classList.add('show');
  clearTimeout(window.__toastTimer);
  window.__toastTimer = setTimeout(()=> t.classList.remove('show'), isError ? 4200 : 2600);
}
function openSuccess(msg){ state.successMsg = msg; render(); }
function closeSuccess(){ state.successMsg = null; render(); }

/* Si algo falla en cualquier parte de la app (por ejemplo en un navegador
   distinto), esto muestra el error en pantalla en vez de quedar en silencio,
   para que el botón nunca "no haga nada" sin explicación. */
window.addEventListener('error', (e)=>{
  try{ showToast('Ocurrió un error: ' + (e.message || 'inténtalo de nuevo.'), true); }catch(_){}
});
window.addEventListener('unhandledrejection', (e)=>{
  try{ showToast('Ocurrió un error: ' + ((e.reason && e.reason.message) || 'inténtalo de nuevo.'), true); }catch(_){}
});

