  if(!val){ box.style.display='none'; box.innerHTML=''; return; }
  const lista = state.data.servicios.filter(s=> (s.vehiculos||[]).includes(val));
  const grupos = {};
  lista.forEach(s=>{ const cat=s.categoria||'Otros'; if(!grupos[cat]) grupos[cat]=[]; grupos[cat].push(s.nombre); });
  let html = `<b>Servicios disponibles para <span style="color:var(--navy)">${val}</span> (${lista.length}):</b><br>`;
  Object.entries(grupos).forEach(([cat,nombres])=>{ html+= `<span style="font-size:12px; color:var(--muted)">${cat}:</span> <span style="font-size:12px;">${nombres.slice(0,4).join(', ')}${nombres.length>4?'…':''}</span><br>`; });
