async function crearCuentaCliente(ev){
  ev.preventDefault();
  const f = ev.target;
  const nombre = f.nombre.value.trim();
  const apellido = f.apellido.value.trim();
  const correo = f.correo.value.trim();
  const telefono = f.telefono.value.trim();
  const whatsapp = f.whatsapp.value.trim();
  const whatsappConsent = !!f.whatsappConsent?.checked;
  const vehiculo = f.vehiculo ? f.vehiculo.value : '';
  const placa = f.placa.value.trim();
  const banner = $('#registro-banner');
  if(!nombre || !apellido || !correo || !telefono || !whatsapp || !vehiculo || !placa){
    banner.textContent = 'Por favor completa todos los campos para crear tu cuenta (incluida la placa).';
    banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
    return;
  }
  const yaExiste = state.data.clientes.some(c => (c.correo||'').trim().toLowerCase() === correo.toLowerCase());
  if(yaExiste){
    banner.textContent = 'Ya existe una cuenta registrada con ese correo.';
    banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
    return;
  }
  const nuevoCliente = {
    id: uid(), nombre: nombre + ' ' + apellido, apellido, correo,
    telefono, whatsapp, whatsappConsent, vehiculo, placa
  };
  state.data.clientes.push(nuevoCliente);
  persist();
  state.session = { role:'cliente', clienteId: nuevoCliente.id };
  state.portalVehiculo = vehiculo;
  state.view = 'portal';
  render();
  openSuccess('¡Cuenta creada correctamente! Bienvenido/a, ' + nombre + '. Vehículo registrado: ' + vehiculo + '. Verás solo servicios para tu tipo de vehículo.');
}
function attemptLogin(){
  const u = $('#login-user').value.trim();
  const p = $('#login-pass').value;
  const auth = state.data.auth || {usuario:'admin', password:'1234'};
  if(u === auth.usuario && p === auth.password){
    state.loginError = '';
    state.session = { role:'admin' };
    goto('dashboard');
  } else {
    state.loginError = 'Usuario o contraseña incorrectos. Intenta de nuevo.';
    render();
  }
}
function attemptClienteLogin(){
  const nombre = $('#cliente-login-nombre').value.trim().toLowerCase();
  const telefono = $('#cliente-login-tel').value.replace(/\D/g, '');
  const match = state.data.clientes.find(c =>
    c.nombre.trim().toLowerCase() === nombre && (c.telefono||'').replace(/\D/g, '') === telefono
  );
  if(match){
    state.loginError = '';
    state.session = { role:'cliente', clienteId: match.id };
    state.portalVehiculo = match.vehiculo || 'Todos';
    goto('portal');
  } else {
    state.loginError = 'No encontramos un cliente con ese nombre y teléfono. Verifica los datos.';
    render();
  }
}
