async function saveServicio(ev){
  ev.preventDefault();
  const f = ev.target;
  const nombre = f.nombre.value.trim();
  const categoria = f.categoria.value;
  const vehiculos = Array.from(f.querySelectorAll('input[name="vehiculos"]:checked')).map(c=>c.value);
  const banner = $('#form-banner');
  if(!nombre){
    banner.textContent = 'Por favor ingresa el nombre del servicio.';
    banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
    return;
  }
  if(!vehiculos.length){
    banner.textContent = 'Selecciona al menos un tipo de vehículo para este servicio.';
    banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
    return;
  }
  const esAceite = categoria === 'Cambio de aceite';
  let opcionesCantidad = null, precio, tipoAceite;
  if(esAceite){
    const c14 = Number(f.precio14.value)||0, c24 = Number(f.precio24.value)||0,
          c34 = Number(f.precio34.value)||0, c44 = Number(f.precio44.value)||0;
    if(!c14 || !c24 || !c34 || !c44){
      banner.textContent = 'Completa el precio para las 4 cantidades de aceite (1/4, 2/4, 3/4 y 1 galón).';
      banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
      return;
    }
    tipoAceite = f.tipoAceite.value.trim() || 'No especificado';
    opcionesCantidad = [
      {cantidad:'1/4', precio:c14}, {cantidad:'2/4', precio:c24},
      {cantidad:'3/4', precio:c34}, {cantidad:'1', precio:c44}
    ];
    precio = c44; // precio de referencia (galón completo) para listados y facturas
  } else {
    precio = Number(f.precio.value);
    if(!precio || precio<=0){
      banner.textContent = 'Por favor ingresa un precio válido.';
      banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
      return;
    }
  }
  const id = f.dataset.id;
  const intervaloKm = Number(f.intervaloKm.value);
  const intervaloDias = Number(f.intervaloDias.value);
  if(!Number.isInteger(intervaloKm)||intervaloKm<1||!Number.isInteger(intervaloDias)||intervaloDias<1){
    banner.textContent = 'Ingresa un intervalo recomendado válido en kilómetros y días.';
    banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
    return;
  }
  let imagenFinal = null;
  const existingForImg = id ? state.data.servicios.find(x=>x.id===id) : null;
  if(state.servicioImagenTemp === '__REMOVE__') imagenFinal = null;
  else if(state.servicioImagenTemp) imagenFinal = state.servicioImagenTemp;
  else if(existingForImg) imagenFinal = existingForImg.imagen || null;
  const payload = {
    nombre, categoria, vehiculos, precio,
    intervaloKm, intervaloDias,
    duracion: f.duracion.value.trim() || '—',
    descripcion: f.descripcion.value.trim(),
    imagen: imagenFinal
  };
  if(esAceite){ payload.tipoAceite = tipoAceite; payload.opcionesCantidad = opcionesCantidad; }
  if(id){
    const existing = state.data.servicios.find(x=>x.id===id);
    delete existing.tipoAceite; delete existing.opcionesCantidad;
    Object.assign(existing, payload);
    recalcularMantenimientosServicio(id);
  }
  else { state.data.servicios.push({id:uid(), ...payload}); }
  state.servicioImagenTemp = null;
  persist();
  closeForm();
  openSuccess(id ? 'Servicio actualizado correctamente.' : 'Servicio creado correctamente.');
}

