  if(!clienteId || !servicioIds.length || !fecha){
    banner.textContent = 'Por favor completa cliente, al menos un tipo de servicio y fecha programada.';
    banner.classList.add('show'); banner.scrollIntoView({behavior:'smooth', block:'center'});
    return;
  }
  const id = f.dataset.id;
  const placa = f.placa.value.trim() || clientePlaca(clienteId);
  const payload = {
    clienteId, servicioIds, fecha, placa,
    descripcion: f.descripcion.value.trim(),
    notificarWhatsapp: f.notificarWhatsapp.checked,
    notificarCorreo: f.notificarCorreo.checked
  };
  let alerta;
  if(id){ alerta=state.data.alertas.find(x=>x.id===id); Object.assign(alerta,payload); }
