/* ================= EXPORTAR / IMPRIMIR ================= */
function exportFacturasCSV(){
  const rows = filteredFacturas();
  let csv = 'Factura,Cliente,Placa,Servicios,Costo,Km actual,Km proximo,Fecha\n';
  rows.forEach(f=>{
    const servicios = serviciosNombres(f.servicioIds).replace(/,/g, ';');
    csv += [f.numero, clienteNombre(f.clienteId), f.placa, servicios, f.costo, f.kmActual??'', f.kmProximo??'', f.fecha].join(',') + '\n';
  });
  const blob = new Blob([csv], {type:'text/csv;charset=utf-8;'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = 'facturas_autocontrol.csv';
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('Facturas exportadas a CSV.');
}
function printFacturas(){
  if(!state.data.facturas.length){ showToast('No hay facturas para imprimir.', true); return; }
  state.facturaPrintPrompt = true;
  render();
}
function cancelarImpresionFacturas(){
  state.facturaPrintPrompt = false;
  render();
}
function confirmarImpresionFacturas(){
  const modo = document.querySelector('input[name="modo-impresion-facturas"]:checked')?.value || 'todas';
  const facturaId = document.getElementById('factura-impresion-select')?.value || '';
  const facturas = modo === 'una'
    ? state.data.facturas.filter(f=>f.id===facturaId)
    : [...state.data.facturas].sort((a,b)=>b.fecha.localeCompare(a.fecha));
  if(!facturas.length){ showToast('Selecciona una factura para imprimir.', true); return; }

  const filas = facturas.map(f=>{
    const cliente = state.data.clientes.find(c=>c.id===f.clienteId);
    const servicios = (f.servicioIds||[]).map(id=>{
      const s = state.data.servicios.find(servicio=>servicio.id===id);
      return s ? s.nombre : '';
    }).filter(Boolean).join(', ');
    return `<tr><td>${esc(f.numero)}</td><td>${esc(cliente?.nombre||'—')}</td><td>${esc(cliente?.vehiculo||'—')}</td><td>${esc(f.placa||'—')}</td><td>${esc(servicios||'—')}</td><td>${esc(fmtMoney(f.costo))}</td><td>${esc(f.fecha||'—')}</td><td>${esc(f.hora||'—')}</td><td>${f.kmActual!=null?esc(f.kmActual.toLocaleString('es-CO')+' km'):'—'}</td><td>${f.kmProximo!=null?esc(f.kmProximo.toLocaleString('es-CO')+' km'):'—'}</td><td>${esc(f.observaciones||'—')}</td></tr>`;
  }).join('');
  const ventana = window.open('', '_blank');
  if(!ventana){ showToast('El navegador bloqueó la ventana de impresión. Permite las ventanas emergentes e inténtalo de nuevo.', true); return; }
  ventana.document.write(`<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Facturas</title><style>@page{size:landscape;margin:12mm}body{font-family:Arial,sans-serif;color:#111;margin:0}table{width:100%;border-collapse:collapse;font-size:10px}th,td{border:1px solid #777;padding:6px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#e9edf2;font-weight:700}thead{display:table-header-group}tr{break-inside:avoid} @media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body><table><thead><tr><th>Factura</th><th>Cliente</th><th>Vehículo</th><th>Placa</th><th>Servicios</th><th>Costo</th><th>Fecha</th><th>Hora</th><th>Km actual</th><th>Próximo km</th><th>Observaciones</th></tr></thead><tbody>${filas}</tbody></table><script>window.onload=()=>window.print();window.onafterprint=()=>window.close();</script></body></html>`);
  ventana.document.close();
  state.facturaPrintPrompt = false;
  render();
}

/* ================= FILTROS ================= */
function filteredFacturas(){
  const q = state.search.facturas;
  return state.data.facturas.filter(f=>{
    if(!q) return true;
    return [f.numero, clienteNombre(f.clienteId), f.placa, serviciosNombres(f.servicioIds)]
      .join(' ').toLowerCase().includes(q);
  }).sort((a,b)=> b.fecha.localeCompare(a.fecha));
}
function filteredServicios(){
  const q = state.search.servicios;
  return state.data.servicios.filter(s=>{
    if(!(s.vehiculos||[]).includes(state.adminServVehiculo)) return false;
    if(!q) return true;
    return [s.nombre, s.categoria].join(' ').toLowerCase().includes(q);
  });
}
function filteredClientes(){
  const q = state.search.clientes;
  return state.data.clientes.filter(c=>{
    if(!q) return true;
    return [c.nombre, c.telefono, c.correo, c.placa].join(' ').toLowerCase().includes(q);
  });
}
function filteredAlertas(){
  const q = state.search.alertas;
  return state.data.alertas.filter(a=>{
    if(!q) return true;
    return [clienteNombre(a.clienteId), a.placa, serviciosNombres(a.servicioIds)].join(' ').toLowerCase().includes(q);
  }).sort((a,b)=> a.fecha.localeCompare(b.fecha));
}
function filteredSolicitudes(){
  const q = state.search.solicitudes;
  return state.data.solicitudes.filter(s=>{
    if(!q) return true;
    return [clienteNombre(s.clienteId), s.placa, serviciosNombres(s.servicioIds)].join(' ').toLowerCase().includes(q);
  }).sort((a,b)=> b.creada.localeCompare(a.creada));
}

