/* ---------- Vista pública: catálogo de servicios y precios ---------- */
function serviciosPorVehiculo(vehiculo){
  return state.data.servicios.filter(s => (s.vehiculos||[]).includes(vehiculo));
}
function serviciosAgrupadosPorCategoria(lista){
  const grupos = {};
  lista.forEach(s=>{
    const cat = s.categoria || 'Otros';
    if(!grupos[cat]) grupos[cat] = [];
    grupos[cat].push(s);
  });
  const ordenCats = ['Cambio de aceite','Filtros','Cambio de bandas','Cambio de llantas','Frenos','Suspensión','Baterías y eléctrico','Mecánica general','Mecánica rápida','Otro','Otros'];
  return Object.entries(grupos).sort((a,b)=>{
    const ia = ordenCats.indexOf(a[0]);
    const ib = ordenCats.indexOf(b[0]);
    if(ia===-1 && ib===-1) return a[0].localeCompare(b[0]);
    if(ia===-1) return 1;
    if(ib===-1) return -1;
    return ia - ib;
  });
}
function renderServiciosPublicos(){
  const vehiculos = ['Motocicleta','Automóvil','Camioneta'];
  const iconos = {Motocicleta:'🏍️', 'Automóvil':'🚗', Camioneta:'🚚'};
  const sel = state.publicVehiculo;
  const lista = serviciosPorVehiculo(sel);
  const grupos = serviciosAgrupadosPorCategoria(lista);

  const secciones = grupos.map(([cat, items]) => {
    const tarjetas = items.map(s => {
      // Izquierda: nombre + precio + detalles, Derecha: imagen representativa
      let precioHtml='';
      if(s.categoria === 'Cambio de aceite' && s.opcionesCantidad){
        const pills = s.opcionesCantidad.map(o => `<span class="pill-precio">${esc(o.cantidad)}: ${fmtMoney(o.precio)}</span>`).join('');
        precioHtml = `<p class="hint" style="margin:2px 0 6px;">Tipo: <b>${esc(s.tipoAceite)}</b> · ${esc(s.duracion)}</p><div class="pill-precio-wrap">${pills}</div>`;
      } else {
        precioHtml = `<div class="servicio-precio" style="margin:4px 0;">${fmtMoney(s.precio)} <span class="hint">· ${esc(s.duracion)}</span></div><p class="hint" style="margin:0;">${esc(s.descripcion||'')}</p>`;
      }
      return `
        <div class="servicio-card servicio-card--split">
          <div class="serv-card-left">
            <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;"><b>${esc(s.nombre)}</b><span class="hint" style="background:#eef1f8;padding:2px 8px;border-radius:20px;font-size:11px;">${esc(servicioVehiculosTxt(s))}</span></div>
            ${precioHtml}
            <p class="hint" style="margin:6px 0 0;font-size:11px;">${esc(s.categoria)}</p>
          </div>
          <div class="serv-card-right">${servicioImagenHtml(s,140)}</div>
        </div>`;
    }).join('');
    return `
      <div class="servicio-categoria">
        <h4 class="categoria-titulo">📌 ${esc(cat)}</h4>
        <div class="servicios-grid">${tarjetas}</div>
      </div>`;
  }).join('');

  return `
    <div class="vehiculo-tabs">
      ${vehiculos.map(v => `
        <button class="vehiculo-tab ${v===sel?'active':''}" onclick="setPublicVehiculo('${v}')">${iconos[v]} ${v}</button>
      `).join('')}
    </div>
    ${secciones || '<p class="hint">No hay servicios registrados para este tipo de vehículo.</p>'}
    <p class="hint" style="text-align:left;margin-top:10px;">Precios y nombres a la izquierda, imagen representativa a la derecha. Solo el administrador puede cambiar las imagenes desde el panel de Servicios.</p>
  `;
}

