/* ---------- Alertas ---------- */
function renderAlertas(){
  const rows = filteredAlertas();
  const trs = rows.length ? rows.map(a=>`
    <tr>
      <td>${esc(clienteNombre(a.clienteId))}</td>
      <td>${esc(a.placa)}</td>
      <td>${esc(serviciosNombres(a.servicioIds))}</td>
      <td>${esc(a.fecha)}</td>
      <td><span class="badge ${a.estado==='pendiente'?'badge-pendiente':'badge-realizada'}">${a.estado==='pendiente'?'Pendiente':'Realizada'}</span></td>
      <td>${a.notificarWhatsapp!==false?'📱':''} ${a.notificarCorreo!==false?'✉️':''}</td>
      <td><div class="row-actions">
        <button class="btn btn-primary btn-icon" title="Enviar recordatorio" onclick="enviarRecordatorio('${a.id}')">📤</button>
        <button class="btn btn-accent btn-icon" title="Editar" onclick="openForm('alerta','${a.id}')">✏️</button>
        <button class="btn btn-outline btn-icon" title="${a.estado==='pendiente'?'Marcar como realizada':'Marcar como pendiente'}" onclick="toggleAlertaEstado('${a.id}')">${a.estado==='pendiente'?'✅':'↺'}</button>
        <button class="btn btn-danger btn-icon" title="Eliminar" onclick="askDelete('alerta','${a.id}')">🗑️</button>
      </div></td>
    </tr>`).join('') : `<tr class="empty-row"><td colspan="7">No hay alertas registradas. Agrega una nueva para hacer seguimiento.</td></tr>`;

  const pend = state.data.alertas.filter(a=>a.estado==='pendiente').length;
  const real = state.data.alertas.filter(a=>a.estado==='realizada').length;

  const inner = `
    <div class="panel">
      <div class="panel-head">
        <h3>Lista de alertas</h3>
        <button class="btn btn-primary" onclick="openForm('alerta')">+ Agregar alerta</button>
      </div>
      <div class="whatsapp-note">📱✉️ Pulsa el botón "Enviar recordatorio" en cada alerta para abrir WhatsApp y/o el correo del cliente, ya redactados y listos para enviar.</div>
      <div class="toolbar">
        <div class="search-box">
          <input id="search-alertas" placeholder="Buscar cliente, placa o servicio..." value="${esc(state.search.alertas)}" onkeydown="searchKeydown('alertas', event)">
          <button class="btn btn-outline" onclick="doSearch('alertas')">Buscar</button>
        </div>
      </div>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Cliente</th><th>Placa</th><th>Tipo de servicio</th><th>Fecha programada</th><th>Estado</th><th>Notificar</th><th>Acciones</th></tr></thead>
          <tbody>${trs}</tbody>
        </table>
      </div>
      <div class="footbar">
        <div class="count-info"><span class="badge badge-pendiente">${pend} pendientes</span> &nbsp; <span class="badge badge-realizada">${real} realizadas</span></div>
        <button class="btn btn-outline btn-sm" onclick="refreshList('alertas')">↻ Actualizar</button>
      </div>
    </div>
  `;
  return renderShell(inner, 'Alertas y recordatorios');
}

/* ---------- Solicitudes de clientes ---------- */
function renderSolicitudes(){
  const rows = filteredSolicitudes();
  const trs = rows.length ? rows.map(s=>{
    const detalles = (s.servicioIds||[]).map(id=>{ const svc=state.data.servicios.find(x=>x.id===id); if(!svc) return ''; return `<div style="margin-bottom:5px;"><b>${esc(svc.nombre)}</b><br><span class="hint">Tipo: ${esc(svc.categoria)}</span></div>`; }).join('');
    const productosMarcas = (s.productosMarcas||'').split(/[,;\n\r]+/).map(item=>item.trim()).filter(Boolean);
    const productosMarcasHtml = productosMarcas.length
      ? `<div style="margin-top:8px;padding-top:7px;border-top:1px solid var(--border);"><b>Producto/marca solicitada:</b><ul style="margin:4px 0 0;padding-left:20px;">${productosMarcas.map(item=>`<li style="margin:2px 0;">${esc(item)}</li>`).join('')}</ul></div>`
      : '';
    const esAceite = (s.servicioIds||[]).some(id=>{ const svc=state.data.servicios.find(x=>x.id===id); return svc && svc.categoria==='Cambio de aceite'; });
    const alertaMant = esAceite ? `<div style="margin-top:6px; background:#fffbeb; border:1px solid #fcd34d; padding:6px 8px; border-radius:8px; font-size:11px;">⚠️ Próximo mantenimiento aceite: 5.000 km o 6 meses. Programar alerta para ${esc(s.fecha) || 'fecha solicitada'} + 6 meses.</div>` : '';
    return `
    <tr>
      <td>${esc(clienteNombre(s.clienteId))}<br><span class="hint">${esc(state.data.clientes.find(c=>c.id===s.clienteId)?.telefono||'')}</span></td>
      <td>${esc(s.placa)}<br><span class="hint">${esc(s.vehiculo||'—')}</span></td>
      <td><div style="max-width:320px;">${detalles||'—'}${productosMarcasHtml}</div>${alertaMant}</td>
      <td><div><b>Fecha:</b> ${esc(s.fecha)||'—'}</div>${s.hora?`<div><b>Preferencia:</b> ${esc(s.hora)}</div>`:''}${s.horaConfirmada?`<div><b>Hora acordada:</b> ${esc(s.horaConfirmada)}</div>`:''}<div class="hint" style="margin-top:5px;">Creada: ${esc(s.creada||'')}</div></td>
      <td><div style="max-width:220px;font-size:12px;white-space:pre-wrap;">${esc(s.observaciones)||'—'}</div></td>
      <td><span class="badge ${s.estado==='pendiente'?'badge-pendiente':'badge-realizada'}">${s.estado==='pendiente'?'Pendiente':'Aceptada'}</span></td>
      <td><div class="row-actions">
        <button class="btn btn-primary btn-icon" title="Crear factura — solo pedirá número de factura" onclick="crearFacturaDesdeSolicitud('${s.id}')">🧾</button>
        <button class="btn btn-outline btn-icon" title="${s.estado==='pendiente'?'Marcar como aceptada':'Marcar como pendiente'}" onclick="toggleSolicitudEstado('${s.id}')">${s.estado==='pendiente'?'✅':'↺'}</button>
        <button class="btn btn-danger btn-icon" title="Eliminar" onclick="askDelete('solicitud','${s.id}')">🗑️</button>
      </div></td>
    </tr>`;
  }).join('') : `<tr class="empty-row"><td colspan="7">Aún no hay solicitudes de clientes. Cuando un cliente elija servicios desde su portal, aparecerán aquí.</td></tr>`;

  const pend = state.data.solicitudes.filter(s=>s.estado==='pendiente').length;
  const atend = state.data.solicitudes.filter(s=>s.estado==='atendida').length;

  const inner = `
    <div class="panel">
      <div class="panel-head">
        <h3>Solicitudes de servicios de clientes</h3>
      </div>
      <p class="hint" style="text-align:left;">Aquí aparecen las compras/solicitudes del cliente. Pulsa 🧾 <b>Crear factura</b> — solo te pedirá el número de factura; el resto se genera automático. Con ✅ marcas la solicitud como <b>Aceptada</b>.</p>
      <div class="toolbar">
        <div class="search-box">
          <input id="search-solicitudes" placeholder="Buscar cliente, placa o servicio..." value="${esc(state.search.solicitudes)}" onkeydown="searchKeydown('solicitudes', event)">
          <button class="btn btn-outline" onclick="doSearch('solicitudes')">Buscar</button>
        </div>
      </div>
      <div class="table-wrap">
        <table>
          <thead><tr><th>Cliente</th><th>Placa</th><th>Servicios solicitados</th><th>Fecha deseada</th><th>Observaciones</th><th>Estado</th><th>Acciones</th></tr></thead>
          <tbody>${trs}</tbody>
        </table>
      </div>
      <div class="footbar">
        <div class="count-info"><span class="badge badge-pendiente">${pend} pendientes</span> &nbsp; <span class="badge badge-realizada">${atend} aceptadas</span></div>
        <button class="btn btn-outline btn-sm" onclick="refreshList('solicitudes')">↻ Actualizar</button>
      </div>
    </div>
  `;
  return renderShell(inner, 'Solicitudes de clientes');
}

function formatoFechaHistorial(fecha){
  if(!fecha) return '—';
  const d = new Date(fecha + 'T00:00:00');
  return Number.isNaN(d.getTime()) ? fecha : d.toLocaleDateString('es-CO',{day:'2-digit',month:'short',year:'numeric'});
}
function etiquetaReglaRecordatorio(regla){
  if(regla.momento === 'mismo-dia') return 'El mismo día del servicio';
  const unidades = {segundo:['segundo','segundos'], minuto:['minuto','minutos'], hora:['hora','horas'], dia:['día','días'], mes:['mes','meses']};
  const unidad = (unidades[regla.unidad] || unidades.dia)[Number(regla.cantidad)===1?0:1];
  return `${regla.cantidad} ${unidad} ${regla.momento==='antes'?'antes':'después'}`;
}
function fechaDeReglaRecordatorio(fechaServicio, regla){
  if(!fechaServicio) return '';
  const [year, month, day] = fechaServicio.split('-').map(Number);
  if(regla.momento === 'mismo-dia') return fechaServicio;
  const milisegundosPorUnidad = {segundo:1000, minuto:60000, hora:3600000};
  if(milisegundosPorUnidad[regla.unidad]){
    const direccion = regla.momento==='despues'?1:-1;
    const objetivo = Date.UTC(year,month-1,day) + direccion * Number(regla.cantidad) * milisegundosPorUnidad[regla.unidad];
    return new Date(objetivo).toISOString().slice(0,10);
  }
  if(regla.unidad === 'mes'){
    const delta = Number(regla.cantidad) * (regla.momento==='antes'?-1:1);
    const monthIndex = year * 12 + (month - 1) + delta;
    const targetYear = Math.floor(monthIndex / 12);
    const targetMonth = ((monthIndex % 12) + 12) % 12;
    const lastDay = new Date(Date.UTC(targetYear, targetMonth + 1, 0)).getUTCDate();
    return `${targetYear}-${String(targetMonth+1).padStart(2,'0')}-${String(Math.min(day,lastDay)).padStart(2,'0')}`;
  }
  const date = new Date(Date.UTC(year, month-1, day + Number(regla.cantidad) * (regla.momento==='antes'?-1:1)));
  return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`;
}
function alertaSiguienteParaFactura(factura){
  const serviceIds = factura.servicioIds || [];
  return (state.data.alertas||[])
    .filter(a=>a.clienteId===factura.clienteId && a.fecha>=factura.fecha && (a.servicioIds||[]).some(id=>serviceIds.includes(id)))
    .sort((a,b)=>a.fecha.localeCompare(b.fecha))[0] || null;
}
function estadoRecordatorioAlerta(alerta){
  if(!alerta) return '<span class="hint">Sin mantenimiento programado</span>';
  if(alerta.estado==='realizada') return '<span class="badge badge-realizada">Servicio realizado</span>';
  const today = fechaHoyBogota();
  const rules = (state.data.config.reglasRecordatorio||[]).filter(r=>r.activo);
  const sent = alerta.recordatoriosEnviados || {};
  const enviadas = rules.filter(r=>sent[r.id] && sent[r.id].fechaProgramada===fechaDeReglaRecordatorio(alerta.fecha,r));
  const pendientes = rules.map(r=>({regla:r, fecha:fechaDeReglaRecordatorio(alerta.fecha,r)}))
    .filter(item=>item.fecha>=today && !(sent[item.regla.id] && sent[item.regla.id].fechaProgramada===item.fecha))
    .sort((a,b)=>a.fecha.localeCompare(b.fecha));
  let html = '';
  if(alerta.fecha<today){
    html += '<div><span class="badge badge-pendiente">🔔 Vencido</span></div>';
  }else if(pendientes.length){
    const next = pendientes[0];
    const proximidad = Math.ceil((new Date(next.fecha+'T00:00:00')-new Date(today+'T00:00:00'))/86400000);
    const status = proximidad<=8 ? 'Próximo' : 'Programado';
    html += `<div><span class="badge ${status==='Próximo'?'badge-pendiente':'badge-realizada'}">🔔 ${status}</span><br><span class="hint">${esc(etiquetaReglaRecordatorio(next.regla))}: ${formatoFechaHistorial(next.fecha)}</span></div>`;
  }
  if(enviadas.length){
    const latest = enviadas.map(r=>({regla:r,log:sent[r.id]})).sort((a,b)=>b.log.enviadoEn.localeCompare(a.log.enviadoEn))[0];
    html += `<div style="margin-top:4px;"><span class="hint">🔔 Enviado: ${esc(etiquetaReglaRecordatorio(latest.regla))}</span></div>`;
  }
  return html || '<span class="hint">Sin recordatorios activos</span>';
}
