async function guardarCambiosHistorial(){
  const dateInputs=Array.from(document.querySelectorAll('.historial-date-input'));
  const fechaInvalida=dateInputs.some(input=>{
    const mantenimiento=state.data.mantenimientos.find(m=>m.id===input.dataset.mantenimiento);
    return mantenimiento&&input.value&&input.value<mantenimiento.fechaServicio;
  });
  if(fechaInvalida){ showToast('La próxima fecha no puede ser anterior al servicio realizado.',true); return; }
  dateInputs.forEach(input=>{
    const mantenimiento=state.data.mantenimientos.find(m=>m.id===input.dataset.mantenimiento);
    if(!mantenimiento||!input.value) return;
    mantenimiento.fechaProxima=input.value;
    const alerta=state.data.alertas.find(a=>a.id===mantenimiento.alertaId);
    if(alerta) alerta.fecha=input.value;
  });
  document.querySelectorAll('.historial-status-select').forEach(select=>{
    const mantenimiento=state.data.mantenimientos.find(m=>m.id===select.dataset.mantenimiento);
    if(!mantenimiento) return;
    mantenimiento.estado=select.value;
    const alerta=state.data.alertas.find(a=>a.id===mantenimiento.alertaId);
    if(alerta) alerta.estado=select.value==='finalizado'?'realizada':'pendiente';
  });
  await persist();
  state.historialEditando=false;
  render();
  showToast('Cambios del historial guardados.');
}
