function estadoRecordatorioTexto(alerta){
  if(alerta.estado==='realizada') return 'Servicio realizado';
  if(alerta.fecha<fechaHoyBogota()) return 'Vencido';
  const rules=(state.data.config.reglasRecordatorio||[]).filter(r=>r.activo);
  const today=fechaHoyBogota();
  return rules.some(r=>fechaDeReglaRecordatorio(alerta.fecha,r)>=today)?'Programado':'Próximo';
}
