function renderFacturaPrintPrompt(){
  if(!state.facturaPrintPrompt) return '';
  const opciones = [...state.data.facturas].sort((a,b)=>b.fecha.localeCompare(a.fecha)).map(f=>
    `<option value="${esc(f.id)}">${esc(f.numero)} · ${esc(clienteNombre(f.clienteId))} · ${esc(f.fecha)}</option>`
  ).join('');
  return `
  <div class="modal-bg show" onclick="if(event.target===this) cancelarImpresionFacturas()">
    <div class="modal-box">
      <div class="modal-icon ask">🖨️</div>
      <h3>Imprimir facturas</h3>
      <div class="field" style="text-align:left;">
        <label class="check-item"><input type="radio" name="modo-impresion-facturas" value="todas" checked onchange="document.getElementById('factura-impresion-select-wrap').style.display='none'"> Todas las facturas</label>
        <label class="check-item"><input type="radio" name="modo-impresion-facturas" value="una" onchange="document.getElementById('factura-impresion-select-wrap').style.display='block'"> Una factura</label>
      </div>
      <div class="field" id="factura-impresion-select-wrap" style="display:none;text-align:left;">
        <label for="factura-impresion-select">Selecciona la factura</label>
        <select id="factura-impresion-select"><option value="">Selecciona una factura</option>${opciones}</select>
      </div>
      <div class="modal-actions">
        <button class="btn btn-primary" onclick="confirmarImpresionFacturas()">Continuar a imprimir</button>
        <button class="btn btn-outline" onclick="cancelarImpresionFacturas()">Cancelar</button>
      </div>
    </div>
  </div>`;
}
function renderHistorialPrintModal(){
  if(!state.historialPrintPrompt) return '';
  return `
  <div class="modal-bg show" onclick="if(event.target===this) cancelarImpresionHistorial()">
    <div class="modal-box">
      <div class="modal-icon ask">🖨️</div>
      <h3>Imprimir historial PDF</h3>
      <div class="field" style="text-align:left;">
        <label for="historial-print-cliente">Selecciona el cliente</label>
        <select id="historial-print-cliente"><option value="">Selecciona un cliente</option>${state.data.clientes.slice().sort((a,b)=>a.nombre.localeCompare(b.nombre,'es')).map(c=>`<option value="${esc(c.id)}" ${c.id===state.historialClienteId?'selected':''}>${esc(c.nombre)} · ${esc(c.placa||'')}</option>`).join('')}</select>
      </div>
      <p>Se abrirá la vista de impresión. Allí puedes elegir “Guardar como PDF”.</p>
      <div class="modal-actions"><button class="btn btn-primary" onclick="confirmarImpresionHistorial()">Continuar</button><button class="btn btn-outline" onclick="cancelarImpresionHistorial()">Cancelar</button></div>
    </div>
  </div>`;
}
function renderRecordatoriosModal(){
  if(!state.recordatoriosPrompt) return '';
  const draft = state.recordatoriosDraft || [];
  const filas = draft.map(r=>`<div data-recordatorio-regla="${esc(r.id)}" style="display:grid;grid-template-columns:auto minmax(70px,1fr) minmax(100px,1fr) minmax(105px,1fr);gap:8px;align-items:center;padding:8px 0;border-bottom:1px solid var(--border);">
    <input aria-label="Activar recordatorio" data-regla-activo type="checkbox" ${r.activo?'checked':''}>
    <input aria-label="Cantidad" data-regla-cantidad type="number" min="0" step="1" value="${Number(r.cantidad)||0}">
    <select aria-label="Unidad" data-regla-unidad><option value="segundo" ${r.unidad==='segundo'?'selected':''}>Segundos</option><option value="minuto" ${r.unidad==='minuto'?'selected':''}>Minutos</option><option value="hora" ${r.unidad==='hora'?'selected':''}>Horas</option><option value="dia" ${r.unidad==='dia'?'selected':''}>Días</option><option value="mes" ${r.unidad==='mes'?'selected':''}>Meses</option></select>
    <select aria-label="Momento" data-regla-momento><option value="antes" ${r.momento==='antes'?'selected':''}>Antes</option><option value="mismo-dia" ${r.momento==='mismo-dia'?'selected':''}>Mismo día</option><option value="despues" ${r.momento==='despues'?'selected':''}>Después</option></select>
  </div>`).join('');
  return `<div class="modal-bg show" onclick="if(event.target===this) cancelarEditorRecordatorios()"><div class="modal-box wide"><div class="panel-head"><h3>Editar días de recordatorios</h3></div><p style="text-align:left;">Activa, desactiva o modifica cada periodo. Los cambios se aplican a las alertas futuras.</p><div style="display:grid;grid-template-columns:auto minmax(70px,1fr) minmax(100px,1fr) minmax(105px,1fr);gap:8px;font-size:12px;font-weight:700;"><span>Activo</span><span>Cantidad</span><span>Unidad</span><span>Momento</span></div>${filas}<div class="form-grid" style="margin-top:14px;"><div class="field"><label for="recordatorio-nueva-cantidad">Agregar periodo</label><input id="recordatorio-nueva-cantidad" type="number" min="1" step="1" value="7"></div><div class="field"><label for="recordatorio-nueva-unidad">Unidad</label><select id="recordatorio-nueva-unidad"><option value="segundo">Segundos</option><option value="minuto">Minutos</option><option value="hora">Horas</option><option value="dia">Días</option><option value="mes">Meses</option></select></div><div class="field"><label for="recordatorio-nuevo-momento">Momento</label><select id="recordatorio-nuevo-momento"><option value="antes">Antes</option><option value="mismo-dia">Mismo día</option><option value="despues">Después</option></select></div></div><div class="form-actions"><button class="btn btn-outline" onclick="agregarReglaRecordatorio()">+ Agregar periodo</button></div><div class="modal-actions" style="margin-top:18px;"><button class="btn btn-primary" onclick="guardarReglasRecordatorio()">Guardar cambios</button><button class="btn btn-outline" onclick="cancelarEditorRecordatorios()">Cancelar</button></div></div></div>`;
}
function renderSolicitudAcceptModal(){
  const p = state.solicitudAcceptPrompt;
  if(!p) return '';
  const s = state.data.solicitudes.find(x=>x.id===p.solicitudId);
  if(!s) return '';
  const nombre = clienteNombre(s.clienteId);
  const servicios = serviciosNombres(s.servicioIds);
  const numero = state.data.clientes.find(c=>c.id===s.clienteId)?.whatsapp || state.data.clientes.find(c=>c.id===s.clienteId)?.telefono || '';
  return `
  <div class="modal-bg show" onclick="if(event.target===this) cancelarAceptacionSolicitud()">
    <div class="modal-box">
      <div class="modal-icon ok">✅</div>
      <h3>Aceptar solicitud</h3>
      <p style="text-align:left;font-size:13px;color:var(--muted);margin-bottom:10px;">Cliente: <b>${esc(nombre)}</b><br>Servicios: <b>${esc(servicios)}</b>${s.productosMarcas?`<br>Producto/marca: <b>${esc(s.productosMarcas)}</b>`:''}<br>Fecha solicitada: <b>${esc(s.fecha||'Sin fecha')}</b><br>Preferencia: <b>${esc(s.hora||'Sin preferencia')}</b><br>WhatsApp: <b>${esc(numero||'No registrado')}</b></p>
      <div class="field" style="text-align:left;">
        <label for="solicitud-hora-confirmada">Hora acordada con el cliente</label>
        <input type="time" id="solicitud-hora-confirmada" required>
        ${p.error ? `<span style="color:#d32f2f;font-size:12px;margin-top:4px;display:block;">${esc(p.error)}</span>` : ''}
      </div>
      <div class="modal-actions">
        <button class="btn btn-primary" onclick="confirmarAceptacionSolicitud()">Aceptar y abrir WhatsApp</button>
        <button class="btn btn-outline" onclick="cancelarAceptacionSolicitud()">Cancelar</button>
      </div>
    </div>
  </div>`;
}
function renderSuccessModal(){
  return `
  <div class="modal-bg show">
    <div class="modal-box">
      <div class="modal-icon ok">✔️</div>
      <h3>Éxito</h3>
      <p style="white-space:pre-line;">${esc(state.successMsg)}</p>
      <div class="modal-actions">
        <button class="btn btn-primary" onclick="closeSuccess()">Aceptar</button>
      </div>
    </div>
  </div>`;
}

/* ================= RENDER PRINCIPAL ================= */
function render(){
  let html = '';
  if(state.view === 'loading'){
    html = `<div class="screen-full"><div style="color:#fff;font-size:16px;">Cargando AutoControl…</div></div>`;
  } else if(state.view === 'welcome'){
    html = renderWelcome();
  } else if(state.view === 'login'){
    html = renderLogin();
  } else if(state.view === 'registro'){
    html = renderRegistro();
  } else if(state.view === 'dashboard'){
    html = renderDashboard();
  } else if(state.view === 'facturas'){
    html = renderFacturas();
  } else if(state.view === 'servicios'){
    html = renderServicios();
  } else if(state.view === 'clientes'){
    html = renderClientes();
  } else if(state.view === 'alertas'){
    html = renderAlertas();
  } else if(state.view === 'solicitudes'){
    html = renderSolicitudes();
  } else if(state.view === 'historial'){
    html = renderHistorial();
  } else if(state.view === 'configuracion'){
    html = renderConfiguracion();
  } else if(state.view === 'portal'){
    html = renderPortal();
  }

  if(state.modal && state.modal.kind === 'form') html += renderFormModal();
  if(state.deleteTarget) html += renderDeleteModal();
  if(state.logoutConfirm) html += renderLogoutModal();
  if(state.desarrolladorasModal) html += renderDesarrolladorasModal();
  if(state.facturaPrompt) html += renderFacturaPromptModal();
  if(state.facturaPrintPrompt) html += renderFacturaPrintPrompt();
  if(state.solicitudAcceptPrompt) html += renderSolicitudAcceptModal();
  if(state.historialPrintPrompt) html += renderHistorialPrintModal();
  if(state.recordatoriosPrompt) html += renderRecordatoriosModal();
  if(state.successMsg) html += renderSuccessModal();

  const nombreTaller = (state.data.config && state.data.config.nombreTaller) || 'Taller Lubricantes Molina';
  document.title = 'AutoControl - ' + nombreTaller;

  // Aplicar foto del local como fondo en vistas públicas
  const fotoLocal = (state.data.config && state.data.config.fotoLocal) || null;
  const vistasPublicas = ['welcome','login','registro','loading'];

  if(fotoLocal && vistasPublicas.includes(state.view)){
    // Escapar comillas en el data URL y aplicar estilos
    const fotoEscapada = fotoLocal.replace(/'/g, "\\'");
    document.body.style.setProperty('background-image', `linear-gradient(rgba(10,14,30,0.78), rgba(10,14,30,0.88)), url('${fotoEscapada}')`, 'important');
    document.body.style.setProperty('background-size', 'cover', 'important');
    document.body.style.setProperty('background-position', 'center', 'important');
    document.body.style.setProperty('background-attachment', 'fixed', 'important');
    document.body.style.setProperty('background-repeat', 'no-repeat', 'important');
  } else {
    // Restaurar fondo predeterminado
    document.body.style.removeProperty('background-image');
    document.body.style.removeProperty('background-size');
    document.body.style.removeProperty('background-position');
    document.body.style.removeProperty('background-attachment');
    document.body.style.removeProperty('background-repeat');
  }

  $('#app').innerHTML = html;
  if(state.view === 'portal'){
    // aplicar filtro de vehículo inicial (para que no se confunda) sin perder selección
    setTimeout(()=>{ try{ applyPortalFiltros((document.getElementById('portal-search')?.value||'').trim().toLowerCase()); applyPortalPreciosFiltro(); }catch(e){} }, 0);
  }
}

/* ================= INICIO ================= */
loadData();

/* Registro del service worker: habilita instalación y uso sin conexión.
   Solo funciona cuando la app está publicada en un servidor (http/https),
   no al abrir el archivo directamente con doble clic (protocolo file://). */
if('serviceWorker' in navigator && location.protocol !== 'file:'){
  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').catch(()=>{});
  });
}
